{"arguments": [
 {"id": "G7", "name": "Naturalistic theories fail to explain the minimal facts", "conclusion": "Naturalistic theories cannot adequately explain the minimal facts, and most critics have given up on them.", "speaker": "Gary Habermas",
  "premises": [
   "P1: The minimal facts (six facts conceded by ~95% of scholars) can give the major refutation of every naturalistic theory.",
   "P2: Most critics today have given up naturalistic theories.",
   "P3: Bart Ehrman says, 'History can't prove miracles, but neither can history disprove miracles.'",
   "P4: More critical scholars now accept either a bodily resurrection or a real appearance experience (Casper view) rather than denying the resurrection entirely."
  ],
  "strength": {
   "st1": {"v": 2, "quote": "If you take this approved list, you can refute you can give the major reputations of every naturalistic theory."},
   "st2": {"v": 2, "quote": "Most critics today have given up naturalistic theories."},
   "st3": {"v": 1, "quote": "Bartman says, \"I won't pick a naturalistic theory.\""},
   "st4": {"v": 0, "quote": "If you take this approved list, you can refute you can give the major reputations of every naturalistic theory."},
   "st5": {"v": 1, "quote": "Critics will generally allow this today that Jesus predicted it ahead of time."},
   "st6": {"v": 1, "quote": "Most critics today have given up naturalistic theories."},
   "st7": {"v": 0, "quote": "It could be a critical comeback."},
   "st8": {"v": 1, "quote": "Bartman, Maurice Casey, James Crossley."}
  },
  "prior_art": "Gary Habermas & Antony Flew, 'Did Jesus Rise from the Dead?', 1987 (minimal-facts method)",
  "originality": {
   "or1": {"v": 1, "quote": "Most critics today have given up naturalistic theories.", "why": "Same minimal-facts-vs-naturalistic-theories argument Habermas has run since the 1980s, updated with newer skeptic names."},
   "or2": {"v": 1, "quote": "More and more critics, they are unbelievers, but they're treating us like it's a draw.", "why": "Adds the Casper-view / 'it's a draw' survey claim as new support."},
   "or3": {"v": 1, "quote": "History can't prove miracles, comma. But neither can history disprove miracles.", "why": "Bridges historiography into the epistemology of miracle claims."},
   "or4": {"v": 0, "quote": "If you take this approved list, you can refute you can give the major reputations of every naturalistic theory.", "why": "No formalization or model is added."}
  },
  "weakest_link": "P1: no naturalistic theory is actually tested against the six facts; the refutation is asserted, not shown.",
  "develop_next": "Take the strongest surviving naturalistic theory and show premise-by-premise which minimal fact it contradicts.",
  "case_map": ["K16", "F4"], "domain": "history"},

 {"id": "G8", "name": "Early testimony unique among world religions", "conclusion": "Christianity has earlier and better-attested historical sources than any other religion or ancient figure.", "speaker": "Gary Habermas",
  "premises": [
   "P1: The earliest sources for Alexander the Great are about 300 years after his death.",
   "P2: Buddhist sources are 600-800 years after Buddha.",
   "P3: Paul Barnett, an Australian historian, says nothing in ancient history, secular or religious, has anything like the early Christian testimony.",
   "P4: Even Bart Ehrman admits we have high Christology texts from 2-3 years after the cross."
  ],
  "strength": {
   "st1": {"v": 2, "quote": "How early? early enough that no other religion in the world has anything like this."},
   "st2": {"v": 2, "quote": "Earliest date for Alexander that we have one of Alexander's writings about him just short of 300 years after he died."},
   "st3": {"v": 1, "quote": "In fact, um Paul Barnett, an Australian historian, says he's taught world religions."},
   "st4": {"v": 1, "quote": "The 600 800 years comprise good history. Don't work."},
   "st5": {"v": 0, "quote": "Buddha not trying to put Buddhism down."},
   "st6": {"v": 1, "quote": "nothing in ancient history, secular or religious, has anything like this."},
   "st7": {"v": 0, "quote": "Don't work."},
   "st8": {"v": 1, "quote": "Bartman says, \"We have several of these high christologology texts from two to three years after the cross.\""}
  },
  "prior_art": "Paul Barnett, 'Is the New Testament Reliable?', 1986 (and standard Christian apologetic comparisons of source-gap dates)",
  "originality": {
   "or1": {"v": 1, "quote": "He says nothing in ancient history, secular or religious, has anything like this.", "why": "A familiar apologetic comparison of testimony dates, here voiced through Barnett and Ehrman."},
   "or2": {"v": 1, "quote": "When you open up page one, here's what the book says to my Christian readers. We don't have what you have.", "why": "Uses a Buddhist-edition preface as fresh comparative evidence."},
   "or3": {"v": 0, "quote": "How about two to three?", "why": "No cross-domain move beyond historiography."},
   "or4": {"v": 0, "quote": "Earliest date for Alexander that we have one of Alexander's writings about him just short of 300 years after he died.", "why": "No formalization or quantitative model."}
  },
  "weakest_link": "P3: the uniqueness claim rests on one authority's assertion rather than a systematic comparison of source-to-event gaps.",
  "develop_next": "Give a table of source-to-event gaps for a fixed set of ancient figures so the comparison is checkable.",
  "case_map": ["K15", "F4"], "domain": "history"}
]}
